import java.io.*;
import java.util.*;

public class Main {
    static final long MOD = 998244353L;
    static long[] fac;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter pw = new PrintWriter(System.out);
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        long K = Long.parseLong(st.nextToken());

        if (K >= N) {
            pw.println(0);
            pw.close();
            return;
        }
        int C = (int) (N - K);

        fac = new long[200001];
        fac[0] = 1L;
        for (int i = 1; i <= 200000; i++) {
            fac[i] = (i * fac[i - 1]) % MOD;
        }

        long ans = 0;
        int sign = 1;
        for (int i = C; i > 0; i--) {
            long val = (choose(C, i) * power(i, N, MOD)) % MOD;
            ans = (ans + sign * val + 2 * MOD) % MOD;
            sign *= -1;
        }

        long mult = 2 * choose(N, C);
        if (C == N)
            mult = 1L;
        pw.println((ans * mult) % MOD);
        pw.close();
    }

    public static long choose(int n, int k) {
        long den = (fac[k] * fac[n - k]) % MOD;
        long denInv = power(den, MOD - 2, MOD);
        return (fac[n] * denInv) % MOD;
    }

    public static long power(long x, int y, long m) {
        long result = 1L;
        x %= m;
        while (y > 0) {
            if ((y & 1) == 1)
                result = (result * x) % m;
            y >>= 1;
            x = (x * x) % m;
        }
        return result;
    }
}
